"use client";
import Link from "next/link"; import {useState} from "react"; import {authService} from "@/lib/services/authService"; import {getErrorMessage} from "@/lib/getErrorMessage";
export default function ForgotPasswordPage(){const[email,setEmail]=useState("");const[otp,setOtp]=useState("");const[password,setPassword]=useState("");const[confirm,setConfirm]=useState("");const[sent,setSent]=useState(false);const[busy,setBusy]=useState(false);const[message,setMessage]=useState("");const[error,setError]=useState("");const request=async(e:React.FormEvent)=>{e.preventDefault();setError("");setMessage("");setBusy(true);try{await authService.requestPasswordReset({email:email.trim()});setSent(true);setMessage("Nếu email hợp lệ, mã OTP sẽ được gửi tới địa chỉ đó. Nếu chưa nhận được, vui lòng kiểm tra Spam hoặc thử lại sau ít phút.")}catch(e){setError(getErrorMessage(e,"Không thể gửi mã OTP"))}finally{setBusy(false)}};const reset=async(e:React.FormEvent)=>{e.preventDefault();setError("");setMessage("");if(password!==confirm)return setError("Mật khẩu xác nhận không khớp.");setBusy(true);try{await authService.resetPassword({email:email.trim(),otp,newPassword:password});setMessage("Đặt lại mật khẩu thành công. Bạn có thể đăng nhập ngay.");setPassword("");setConfirm("")}catch(e){setError(getErrorMessage(e,"Mã OTP không đúng hoặc đã hết hạn"))}finally{setBusy(false)}};return <main className="mx-auto flex min-h-[80vh] max-w-md flex-col justify-center px-5 py-12"><p className="font-display text-sm italic text-accent">Lấy lại quyền truy cập</p><h1 className="mt-1 font-display text-3xl text-ink">Quên mật khẩu</h1><p className="mt-2 text-sm text-neutral-500">Nhập email đã đăng ký để nhận mã OTP.</p>{(error||message)&&<p className={`mt-5 text-sm ${error?"text-red-600":"text-primary"}`}>{error||message}</p>}{!sent?<form onSubmit={request} className="mt-8 space-y-4"><input type="email" required placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} className="w-full rounded-lg border border-line bg-surface px-3 py-2.5 text-sm text-ink focus:border-primary focus:outline-none"/><button disabled={busy} className="w-full rounded-full bg-primary py-3 text-sm font-semibold text-white hover:bg-primary-dark disabled:opacity-50">{busy?"Đang gửi...":"Gửi mã OTP"}</button></form>:<form onSubmit={reset} className="mt-8 space-y-4"><input required maxLength={6} inputMode="numeric" pattern="[0-9]{6}" placeholder="Mã OTP 6 số" value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,""))} className="w-full rounded-lg border border-line bg-surface px-3 py-3 text-center text-2xl tracking-[0.5em] text-ink focus:border-primary focus:outline-none"/><input type="password" required minLength={6} placeholder="Mật khẩu mới" value={password} onChange={e=>setPassword(e.target.value)} className="w-full rounded-lg border border-line bg-surface px-3 py-2.5 text-sm text-ink focus:border-primary focus:outline-none"/><input type="password" required minLength={6} placeholder="Xác nhận mật khẩu mới" value={confirm} onChange={e=>setConfirm(e.target.value)} className="w-full rounded-lg border border-line bg-surface px-3 py-2.5 text-sm text-ink focus:border-primary focus:outline-none"/><button disabled={busy||otp.length!==6} className="w-full rounded-full bg-primary py-3 text-sm font-semibold text-white hover:bg-primary-dark disabled:opacity-50">{busy?"Đang cập nhật...":"Đặt lại mật khẩu"}</button></form>}<p className="mt-6 text-center text-sm text-neutral-500"><Link href="/login" className="font-medium text-primary hover:underline">Quay lại đăng nhập</Link></p></main>}
